test("名前を持つ祖先が無いノードの欠落は、その子を収める artboard のパスで報告される", () => {
  const document = DesignDocument.create({
    tokens: DocumentTemplate.Default.tokens,
    artboards: [
      { name: "screen", width: 375, height: 812, children: [] },
      {
        name: "",
        width: 375,
        height: 812,
        children: [{ name: "", type: "Box" }],
      },
    ],
  });

  const errors = DesignDocument.collectErrors(document).filter(
    (error) => error.kind === "missing-name",
  );

  expect(errors).toEqual([
    expect.objectContaining({
      documentPath: "artboards[1]",
      message: 'artboard 1 of "artboards" has no name',
    }),
    expect.objectContaining({
      documentPath: "artboards[1]",
      message: 'child 0 of artboard 1 of "artboards" has no name',
    }),
  ]);
});

test("名前を持つ祖先が無い部品内部のノードの欠落は、components のパスで報告される", () => {
  const document = DesignDocument.create({
    tokens: DocumentTemplate.Default.tokens,
    components: { "": { type: "Box", children: [{ name: "", type: "Box" }] } },
  });

  const errors = DesignDocument.collectErrors(document).filter(
    (error) => error.kind === "missing-name",
  );

  expect(errors).toEqual([
    expect.objectContaining({
      documentPath: "components",
      message: 'key "" of "components" has no name',
    }),
    expect.objectContaining({
      documentPath: "components",
      message: 'child 0 of key "" of "components" has no name',
    }),
  ]);
});

test("名前を持つ祖先が無い子ノードの欠落のエラーは、ルートのパスで指し、ノード名も prop も持たない", () => {
  const document = DesignDocument.create({
    tokens: DocumentTemplate.Default.tokens,
    artboards: [
      {
        name: "",
        width: 375,
        height: 812,
        children: [{ name: "", type: "Box" }],
      },
    ],
  });

  const errors = DesignDocument.collectErrors(document).filter(
    (error) => error.kind === "missing-name",
  );

  expect(errors[1]).toStrictEqual({
    kind: "missing-name",
    documentPath: "artboards[0]",
    message: 'child 0 of artboard 0 of "artboards" has no name',
  });
});

test("子ノードの名前が欠落したときのエラーは、名前を持つ最も近い祖先の位置で、子の添字を挙げる", () => {
  const errors = errorsOf({}, [
    { name: "label", type: "Text" },
    { name: "", type: "Text" },
  ]);

  expect(errors).toStrictEqual([
    {
      kind: "missing-name",
      nodeName: "screen",
      message: 'child 1 of "screen" has no name',
    },
  ]);
});

test("名前を持つ祖先が無い子ノードは、その子を収める artboard を指すドキュメント内のパスのエラーになる", () => {
  const document = DesignDocument.create({
    tokens: TokenSet.empty(),
    artboards: [
      {
        name: "",
        width: 375,
        height: 812,
        children: [{ name: "", type: "Box" }],
      },
    ],
  });

  expect(
    DocumentError.collectFrom(document)
      .filter((error) => error.kind === "missing-name")
      .map((error) => error.location),
  ).toStrictEqual([
    { kind: "document-path", path: "artboards[0]" },
    { kind: "document-path", path: "artboards[0]" },
  ]);
});

test("名前が欠落した子ノードは、名前を持つ親ノードを指すエラーになる", () => {
  const document = DesignDocument.create({
    tokens: TokenSet.empty(),
    artboards: [
      {
        name: "screen",
        width: 375,
        height: 812,
        children: [{ name: "", type: "Box" }],
      },
    ],
  });

  expect(
    DocumentError.collectFrom(document).map((error) => error.location),
  ).toStrictEqual([{ kind: "node", nodeName: "screen" }]);
});

