function namedOwnerOr(name: string, fallback: ChildOwner): ChildOwner {
  return name ? { kind: "named", name } : fallback;
}

/**
 * ノードの並びとその子孫の名前の出現を、行きがけ順に並べる。
 *
 * @param nodes 並べるノードの兄弟の並び
 * @param owner 兄弟の欠落を報告するときの入れ物
 * @returns 各ノードの名前の出現と、その子孫の出現を行きがけ順に並べたもの
 */
function collectNodeOccurrences(
  nodes: readonly Node[],
  owner: ChildOwner,
): readonly NameOccurrence[] {
  return nodes.flatMap((node, index): readonly NameOccurrence[] => [
    { name: node.name, position: { kind: "child", owner, index } },
    ...collectNodeOccurrences(
      Node.children(node),
      namedOwnerOr(node.name, owner),
    ),
  ]);
}

/** 名前空間のルート（部品定義・artboard）1 つの、名前と位置と子ノード。 */
type NamespaceRoot = Readonly<{
  name: string;
  position: RootPosition;
  children: readonly Node[];
}>;

/**
 * ルート 1 つ分の名前の出現を集める。
 *
 * @param root 集めるルート
 * @returns ルート自身の名前の出現と、配下のノードの出現を行きがけ順に並べたもの
 */
function collectRootOccurrences({
  name,
  position,
  children,
}: NamespaceRoot): readonly NameOccurrence[] {
  return [
    { name, position },
    ...collectNodeOccurrences(children, namedOwnerOr(name, position)),
  ];
}

function toMissingNameErrorLocation(
  position: NamePosition,
): Readonly<{ location: MissingNameLocation; subject: string }> {
  switch (position.kind) {
    case "component-key":
    case "artboard":
      return toOwnerErrorLocation(position);
    case "child": {
      const { location, subject } = toOwnerErrorLocation(position.owner);
      return { location, subject: `child ${position.index} of ${subject}` };
    }
  }
}

/**
 * 名前が欠落した位置を、報告用のエラーにする。
 *
 * @param position 名前が欠落した位置
 * @returns `toMissingNameErrorLocation` の位置を持ち、`<主語> has no name` をメッセージに持つ
 *   missing-name
 */
function toMissingNameError(
  position: NamePosition,
): NodeValidationError | UnnamedRootValidationError {
  const { location, subject } = toMissingNameErrorLocation(position);
  return {
    kind: "missing-name",
    ...location,
    message: `${subject} has no name`,
  };
}
